#!/usr/bin/env bash
# Enforces a minimum line-coverage floor for the Flutter app.
#
# Usage: bash scritps/check_test_coverage.sh [threshold-percent]
#
# Reads coverage/lcov.info (generated by `flutter test --coverage`) and fails
# when total line coverage is below the given threshold (default: 4).
# The floor is a ratchet: raise it as coverage improves.

set -euo pipefail

THRESHOLD="${1:-4}"
LCOV="${LCOV:-coverage/lcov.info}"

if [[ ! -f "$LCOV" ]]; then
  echo "::error::$LCOV not found. Run 'flutter test --coverage' first."
  exit 1
fi

HIT=$(awk -F': *' '/^LH:/ {h += $2} END {print h + 0}' "$LCOV")
FOUND=$(awk -F': *' '/^LF:/ {f += $2} END {print f + 0}' "$LCOV")

if [[ "$FOUND" -eq 0 ]]; then
  echo "::error::No instrumented lines found in $LCOV"
  exit 1
fi

PERCENT=$((HIT * 100 / FOUND))

echo "Line coverage: ${PERCENT}% (${HIT}/${FOUND} lines), floor: ${THRESHOLD}%"

if [[ "$PERCENT" -lt "$THRESHOLD" ]]; then
  echo "::error::Line coverage ${PERCENT}% is below the ${THRESHOLD}% floor"
  exit 1
fi
